import { readFile, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { runTool } from './process';
import { DEFAULT_TOOL_CONFIG } from './probe';
import { synthesizeClip } from './qualify';

/** Real media fixtures generated by ffmpeg at test time (no binary fixtures in git). */
export type FixtureName =
  | 'h264-aac'
  | 'h264-silent'
  | 'vp9-opus'
  | 'vp8-silent'
  | 'rotated'
  | 'high444'
  | 'mpeg4'
  | 'long'
  | 'big';

const SPECS: Record<FixtureName, Parameters<typeof synthesizeClip>[2] & { ext: string }> = {
  'h264-aac': {
    ext: 'mp4',
    seconds: 2,
    size: '320x240',
    args: ['-c:v', 'libx264', '-pix_fmt', 'yuv420p', '-c:a', 'aac'],
  },
  'h264-silent': {
    ext: 'mp4',
    seconds: 2,
    size: '320x240',
    audio: false,
    args: ['-c:v', 'libx264', '-pix_fmt', 'yuv420p'],
  },
  'vp9-opus': {
    ext: 'webm',
    seconds: 3,
    size: '320x180',
    args: ['-c:v', 'libvpx-vp9', '-deadline', 'realtime', '-cpu-used', '8', '-c:a', 'libopus'],
  },
  'vp8-silent': {
    ext: 'webm',
    seconds: 2,
    size: '160x120',
    audio: false,
    args: ['-c:v', 'libvpx'],
  },
  rotated: {
    ext: 'mp4',
    seconds: 2,
    size: '320x180',
    args: ['-c:v', 'libx264', '-pix_fmt', 'yuv420p', '-c:a', 'aac'],
  },
  high444: {
    ext: 'mp4',
    seconds: 2,
    size: '320x240',
    audio: false,
    args: ['-c:v', 'libx264', '-pix_fmt', 'yuv444p'],
  },
  mpeg4: { ext: 'mp4', seconds: 1, size: '160x120', audio: false, args: ['-c:v', 'mpeg4'] },
  // >8 MiB so it needs two multipart parts.
  big: {
    ext: 'mp4',
    seconds: 1,
    size: '640x360',
    rate: 30,
    audio: false,
    args: [
      '-vf',
      'noise=alls=60:allf=t',
      '-c:v',
      'libx264',
      '-preset',
      'ultrafast',
      '-crf',
      '1',
      '-pix_fmt',
      'yuv420p',
    ],
  },
  long: {
    ext: 'mp4',
    seconds: 4,
    size: '160x120',
    args: ['-c:v', 'libx264', '-pix_fmt', 'yuv420p', '-c:a', 'aac'],
  },
};

export async function makeFixture(dir: string, name: FixtureName): Promise<Buffer> {
  const spec = SPECS[name];
  const path = join(dir, `${name}.${spec.ext}`);
  await synthesizeClip(DEFAULT_TOOL_CONFIG, path, spec);
  if (name === 'rotated') {
    // Phone-style display matrix: stored landscape, displayed portrait.
    const rotated = join(dir, 'rotated-display.mp4');
    await runTool(
      'ffmpeg',
      [
        '-nostdin',
        '-v',
        'error',
        '-display_rotation',
        '90',
        '-i',
        path,
        '-c',
        'copy',
        '-y',
        rotated,
      ],
      { timeoutMs: 30_000 },
    );
    return readFile(rotated);
  }
  return readFile(path);
}

/** Valid container, damaged video payload in the middle of the file. */
export function corrupt(bytes: Buffer): Buffer {
  const out = Buffer.from(bytes);
  const start = Math.floor(out.length / 3);
  for (let i = start; i < Math.min(out.length, start + 4000); i++)
    out[i] = (out[i]! * 7 + 13) & 255;
  return out;
}

export async function writeFixture(dir: string, name: string, bytes: Buffer): Promise<string> {
  const path = join(dir, name);
  await writeFile(path, bytes);
  return path;
}
